import styled from '@emotion/styled';

export const StyledChartsGrid = styled.div({
  display: 'grid',
  gridTemplateColumns: '3fr 1fr',
  paddingBottom: '0',
});

export const StyledLineChartColumn = styled.div({
  display: 'flex',
  flexDirection: 'column',
  minWidth: 0,
  position: 'relative',
});

export const StyledBarChartColumn = styled.div({
  display: 'flex',
  flexDirection: 'column',
  minWidth: 0,
});

export const StyledChartWrapper = styled.div({
  height: '286px',
});
